mapper.update:
UPDATE inventory
SET cost_amount      = ROUND((quantity - #{qty}) * cost_price, 2),
    quantity         = quantity - #{qty},
    last_change_time = NOW(),
    version          = version + 1
WHERE goods_id = #{goodsId}
  AND store_id = #{storeId}

  AND quantity >= #{qty}

mapper.select:
SELECT goods_id, store_id, quantity, cost_price, cost_amount,
       last_change_time, version, update_time
FROM inventory
WHERE goods_id = #{goodsId}
  AND store_id = #{storeId}
FOR UPDATE

SELECT ir.unit_cost
FROM inventory_record ir
WHERE ir.goods_id = #{goodsId}
  AND ir.store_id = #{storeId}
ORDER BY ir.operate_time DESC, ir.id DESC
LIMIT 1
